  min-height: 0; /* 关键属性：防止内容溢出 */
  overflow: hidden;
  position: relative;
  display: flex;
  flex-direction: column;
}
.auto-height .sc-table-content-wrapper[data-v-7e65f09b] {
  flex: none;
  height: auto;
  min-height: 300px;
  overflow-y: auto;
}
.sc-table-drag-actions[data-v-7e65f09b] {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 16px;
  background: linear-gradient(135deg, var(--el-color-warning-light-9) 0%, var(--el-color-warning-light-8) 100%);
  border-radius: 8px;
  margin-bottom: 12px;
  border: 1px solid var(--el-color-warning-light-5);
}
.sc-table-drag-actions .drag-action-info[data-v-7e65f09b] {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--el-color-warning);
  font-size: 14px;
  font-weight: 500;
}
.sc-table-drag-actions .drag-action-buttons[data-v-7e65f09b] {
  display: flex;
  gap: 8px;
}
.sc-table-pagination-wrapper[data-v-7e65f09b] {
  flex-shrink: 0; /* 防止分页区域被压缩 */
  padding: 10px 0;
  width: 100%;
  padding-top: 16px;
  border-radius: 12px;
  box-shadow: 0 2px 12px rgba(0, 0, 0, 0.04);
}
/* 确保表格内容区域不会被分页挤压 */
[data-v-7e65f09b] .el-table__body-wrapper {
  overflow: auto !important;
  height: auto !important;
  flex: 1;
}
[data-v-7e65f09b] .el-table {
  height: 100% !important;
  display: flex;
  flex-direction: column;
}
[data-v-7e65f09b] .el-table__inner-wrapper {
  height: 100% !important;
  display: flex;
  flex-direction: column;
}
[data-v-7e65f09b] .el-table__header-wrapper {
  width: 100%;
  flex-shrink: 0;
}
/* 表头固定样式 */
